-- returns 200 rows

-- Then, once per author (200 times total):
SELECT id, title FROM posts WHERE author_id = 7;
SELECT id, title FROM posts WHERE author_id = 14;
-- ... 198 more individual queries ...

-- Total: 201 round trips to answer one logical question.

