-- Client A's transaction, borrowing physical connection #7 from the pool:
BEGIN;
SET search_path = tenant_a;
SELECT * FROM orders LIMIT 1;
COMMIT;
-- Transaction-mode pooling returns connection #7 to the pool here.
-- search_path is STILL set to tenant_a on this physical connection --
-- nothing reset it.

-- Client B's transaction, unluckily borrowing the SAME physical
-- connection #7 next:
BEGIN;
SELECT * FROM orders LIMIT 1;   -- unexpectedly queries tenant_a's schema!
COMMIT;

-- Fix: scope the setting to the transaction instead of the session.
BEGIN;
SET LOCAL search_path = tenant_a;   -- automatically undone at COMMIT/ROLLBACK
SELECT * FROM orders LIMIT 1;
COMMIT;
-- Connection #7 returns to the pool with search_path back to its default.

